// ===== CROSS-PLATFORM CONTENT ADAPTER =====
// Takes IG carousel content and adapts it for other platforms

const staticData = $getWorkflowStaticData('global');
const posts = staticData.posts || [];
const kb = staticData.knowledgeBase || {};
const niche = staticData.niche || 'general';

// Get the latest post to syndicate
const latestPost = posts[posts.length - 1];
if (!latestPost) {
  return [{ json: { noPost: true } }];
}

// Platform-specific adaptations
const adaptations = {
  // Pinterest - Vertical pins
  pinterest: {
    format: 'pin',
    dimensions: '1000x1500',
    title: latestPost.hook,
    description: `${latestPost.caption}\n\n#${kb.topHashtags?.slice(0, 10).join(' #') || niche}`,
    keywords: kb.topHashtags || [niche],
    boardSuggestion: `${niche} Tips`,
    designChanges: 'Vertical format, larger text, bold colors'
  },

  // Twitter/X - Thread format
  twitter: {
    format: 'thread',
    tweets: [
      `🧵 THREAD: ${latestPost.hook}\n\n(1/${latestPost.slideCount + 2})`,
      ...generateTweetThread(latestPost, kb),
      `\n\nFollow for more ${niche} content! 🔥\n\nLike + Retweet if this helped! 🙏`
    ],
    hashtags: kb.topHashtags?.slice(0, 3).join(' ') || niche
  },

  // LinkedIn - Professional post
  linkedin: {
    format: 'post',
    content: generateLinkedInPost(latestPost, kb, niche),
    hashtags: kb.topHashtags?.slice(0, 5).map(h => `#${h}`).join(' ') || `#${niche}`,
    tone: 'professional but engaging'
  },

  // Facebook Groups
  facebook: {
    format: 'post',
    content: generateFacebookPost(latestPost, kb, niche),
    groups: findRelevantGroups(niche),
    tone: 'conversational, community-focused'
  },

  // TikTok - Script for reel
  tiktok: {
    format: 'script',
    hook: latestPost.hook,
    script: generateTikTokScript(latestPost, kb, niche),
    duration: '30-60 seconds',
    trending_audio: kb.trendingAudio?.[0] || 'Use trending sound',
    hashtags: kb.trendingHashtags?.slice(0, 5) || [niche]
  },

  // YouTube Shorts
  youtube_shorts: {
    format: 'script',
    title: latestPost.hook,
    script: generateYouTubeShortsScript(latestPost, kb, niche),
    thumbnail_style: 'Bold text, shocked face, bright colors',
    description: `${latestPost.caption}\n\n#${kb.topHashtags?.slice(0, 10).join(' #') || niche}`
  },

  // Reddit
  reddit: {
    format: 'post',
    title: generateRedditTitle(latestPost, niche),
    content: generateRedditPost(latestPost, kb, niche),
    subreddits: findRelevantSubreddits(niche),
    tone: 'helpful, no self-promotion'
  }
};

function generateTweetThread(post, kb) {
  const slides = post.slideCount || 7;
  const tweets = [];
  for (let i = 1; i < slides; i++) {
    tweets.push(`Here's point ${i}: [Key insight from slide ${i + 1}]\n\n(${i + 1}/${slides + 2})`);
  }
  return tweets;
}

function generateLinkedInPost(post, kb, niche) {
  return `I've been studying ${niche} for the past few weeks.\n\nHere's what I found:\n\n${post.hook}\n\n[Key insights from the carousel]\n\nThe biggest lesson? [Main takeaway]\n\nWhat's your experience with ${niche}? Drop your thoughts below. 👇`;
}

function generateFacebookPost(post, kb, niche) {
  return `Hey everyone! 👋\n\nI wanted to share something I've been learning about ${niche}.\n\n${post.hook}\n\n[Share key points from carousel]\n\nWhat do you think? Have you experienced this too?\n\nWould love to hear your thoughts! 💬`;
}

function generateTikTokScript(post, kb, niche) {
  return `[HOOK - 3 seconds]\n"${post.hook}"\n\n[PROBLEM - 5 seconds]\n"Here's the problem most people face with ${niche}..."\n\n[SOLUTION - 15 seconds]\n"But here's what actually works..."\n\n[PROOF - 10 seconds]\n"And here are the results..."\n\n[CTA - 5 seconds]\n"Follow for more ${niche} tips!"`;
}

function generateYouTubeShortsScript(post, kb, niche) {
  return `[HOOK]\n"${post.hook}"\n\n[CONTENT]\n[Deliver value from carousel in engaging way]\n\n[CTA]\n"Subscribe for more ${niche} content!"`;
}

function generateRedditTitle(post, niche) {
  return `I've been researching ${niche} for weeks - here's what actually works`;
}

function generateRedditPost(post, kb, niche) {
  return `Hey r/${niche.replace(/\s+/g, '')},\n\nI've been deep-diving into ${niche} and wanted to share some findings.\n\n[Share genuine value from research]\n\nHappy to answer any questions in the comments!`;
}

function findRelevantGroups(niche) {
  return [`${niche} community`, `${niche} tips`, `${niche} beginners`];
}

function findRelevantSubreddits(niche) {
  return [`r/${niche.replace(/\s+/g, '')}`, `r/${niche.replace(/\s+/g, '')}tips`];
}

return [{
  json: {
    latestPost,
    adaptations,
    chatId: staticData.chatId,
    niche
  }
}];

// ===== POST TO PINTEREST =====

const input = $input.first().json;
const { adaptations, chatId } = input;
const pinterest = adaptations.pinterest;

// Pinterest API posting
const pinData = {
  board: pinterest.boardSuggestion,
  title: pinterest.title,
  description: pinterest.description,
  // Image URL from carousel
  image_url: input.latestPost.imageUrls?.[0] || '',
  link: '' // Add website link if available
};

return [{
  json: {
    platform: 'pinterest',
    data: pinData,
    status: 'ready',
    chatId
  }
}];

// ===== POST TO TWITTER/X =====

const input = $input.first().json;
const { adaptations, chatId } = input;
const twitter = adaptations.twitter;

// Twitter thread data
const threadData = {
  tweets: twitter.tweets,
  hashtags: twitter.hashtags
};

return [{
  json: {
    platform: 'twitter',
    data: threadData,
    status: 'ready',
    chatId
  }
}];

// ===== POST TO LINKEDIN =====

const input = $input.first().json;
const { adaptations, chatId } = input;
const linkedin = adaptations.linkedin;

const linkedinData = {
  content: linkedin.content,
  hashtags: linkedin.hashtags
};

return [{
  json: {
    platform: 'linkedin',
    data: linkedinData,
    status: 'ready',
    chatId
  }
}];

// ===== GENERATE TIKTOK SCRIPT =====

const input = $input.first().json;
const { adaptations, chatId } = input;
const tiktok = adaptations.tiktok;

const scriptData = {
  hook: tiktok.hook,
  script: tiktok.script,
  duration: tiktok.duration,
  trending_audio: tiktok.trending_audio,
  hashtags: tiktok.hashtags
};

return [{
  json: {
    platform: 'tiktok',
    data: scriptData,
    status: 'script_ready',
    chatId
  }
}];

// ===== AGGREGATE ALL PLATFORM POSTS =====

const input = $input.all();
const chatId = input[0]?.json.chatId;

const platformSummary = input.map(item => {
  const { platform, status } = item.json;
  return `${platform}: ${status === 'ready' ? '✅' : '📝'}`;
});

return [{
  json: {
    chatId,
    platforms: input.map(i => i.json),
    summary: platformSummary
  }
}];
